'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var uniform = require( '@stdlib/random/array/uniform' );
var ones = require( '@stdlib/array/ones' );
var isString = require( '@stdlib/assert/is-string' );
var floor = require( '@stdlib/math/base/special/floor' );
var pow = require( '@stdlib/math/base/special/pow' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dlaqsy = require( './../lib/dlaqsy.js' );


// VARIABLES //

var LAYOUTS = [
	'row-major',
	'column-major'
];
var UPLOS = [
	'upper',
	'lower'
];
var options = {
	'dtype': 'float64'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {string} uplo - specifies whether to reference the upper or lower triangular part of the matrix
* @param {PositiveInteger} N - number of elements along each dimension
* @returns {Function} benchmark function
*/
function createBenchmark( order, uplo, N ) {
	var A;
	var S;

	A = uniform( N*N, -10.0, 10.0, options );

	// Use unit scale factors so that repeated equilibration does not overflow or underflow:
	S = ones( N, options.dtype );
	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var equed;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			equed = dlaqsy( order, uplo, N, A, N, S, 0.01, 10.0 );
			if ( !isString( equed ) ) {
				b.fail( 'should return a string' );
			}
		}
		b.toc();
		if ( !isString( equed ) ) {
			b.fail( 'should return a string' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var uplo;
	var min;
	var max;
	var ord;
	var N;
	var f;
	var i;
	var j;
	var k;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( k = 0; k < LAYOUTS.length; k++ ) {
		ord = LAYOUTS[ k ];
		for ( j = 0; j < UPLOS.length; j++ ) {
			uplo = UPLOS[ j ];
			for ( i = min; i <= max; i++ ) {
				N = floor( pow( pow( 10, i ), 1.0/2.0 ) );
				f = createBenchmark( ord, uplo, N );
				bench( format( '%s::square_matrix:order=%s,uplo=%s,size=%d', pkg, ord, uplo, N*N ), f );
			}
		}
	}
}

main();
